const source=$input.first()?.json??{};const p=(source.review_request&&typeof source.review_request==='object')?source.review_request:source;
const missing=[];for(const k of ['task_id','project_id','artifact_id','artifact_revision'])if(typeof p[k]!=='string'||!p[k].trim())missing.push(k);
const requirements=Array.isArray(p.requirements)?p.requirements:[];if(!requirements.length)missing.push('approved_requirements');
if(p.brief_approved!==true)missing.push('approved_brief');
const art=p.artifact&&typeof p.artifact==='object'?p.artifact:{};
const validScopes=['TEXT','IMAGE','VIDEO','AUDIO'];
const rawScopes=Array.isArray(p.requested_scopes)?p.requested_scopes:[];
const requested_scopes=rawScopes.filter(s=>typeof s==='string'&&validScopes.includes(s));
if(!rawScopes.length||new Set(requested_scopes).size!==rawScopes.length)missing.push('explicit_valid_requested_scopes');
const kind=typeof art.kind==='string'?art.kind.toUpperCase():'UNKNOWN';
const allowable={TEXT:['TEXT'],IMAGE:['TEXT','IMAGE'],VIDEO:['TEXT','IMAGE','VIDEO','AUDIO'],AUDIO:['TEXT','AUDIO']};
if(!allowable[kind])missing.push('valid_artifact_kind');else if(requested_scopes.some(s=>!allowable[kind].includes(s)))missing.push('scope_incompatible_with_artifact_kind');
const bar=p.bar&&typeof p.bar==='object'?p.bar:{};
const mediaReview=requested_scopes.some(s=>s!=='TEXT');
if(mediaReview&&(p.bar_approved!==true||!Array.isArray(bar.mechanics)||bar.mechanics.length<5||bar.mechanics.length>7))missing.push('approved_bar_5_to_7_mechanics');
if(mediaReview&&(typeof p.benchmark_ref!=='string'||!p.benchmark_ref.trim()))missing.push('accessible_benchmark');
const canon=p.canon&&typeof p.canon==='object'?p.canon:{};
if(p.review_phase!==undefined&&!['TEXT_PRECHECK','FINAL_MEDIA'].includes(p.review_phase))missing.push('invalid_review_phase');
const review_phase=(p.review_phase==='TEXT_PRECHECK'||p.review_phase==='FINAL_MEDIA')?p.review_phase:(kind==='TEXT'&&requested_scopes.length===1&&requested_scopes[0]==='TEXT'?'TEXT_PRECHECK':'FINAL_MEDIA');
if(review_phase==='TEXT_PRECHECK'&&(kind!=='TEXT'||requested_scopes.length!==1||requested_scopes[0]!=='TEXT'))missing.push('text_precheck_requires_text_artifact_and_text_only_scope');
if(review_phase==='TEXT_PRECHECK'&&(!art.text_ref||typeof art.text_ref!=='string'))missing.push('text_artifact_source_reference');
const required_reviewers=review_phase==='TEXT_PRECHECK'?['REVIEW-REQ','REVIEW-SYSTEM']:['REVIEW-REQ','REVIEW-SYSTEM','REVIEW-CRAFT'];
const pack={review_phase,required_reviewers,task_id:p.task_id??null,project_id:p.project_id??null,artifact_id:p.artifact_id??null,artifact_revision:p.artifact_revision??null,
review_round:Number.isInteger(p.review_round)&&p.review_round>0?p.review_round:1,artifact_scope:kind,requested_scopes,
requirements,canon:{revision:canon.revision??null,rules:Array.isArray(canon.rules)?canon.rules:[]},
bar:{revision:bar.revision??null,mechanics:Array.isArray(bar.mechanics)?bar.mechanics:[]},
benchmark_ref:p.benchmark_ref??null,artifact:{kind:art.kind??'unknown',render_refs:Array.isArray(art.render_refs)?art.render_refs:[],text_ref:art.text_ref??null},
missing,safe_mode:'DRAFT_NO_LLM_NO_COST',trusted_backend_evidence_available:false,untrusted_approval_ignored:true};
return[{json:pack}];

const a=$input.all().map(x=>x.json);
const roles=['REVIEW-REQ','REVIEW-SYSTEM','REVIEW-CRAFT'];
const counts={};for(const x of a)counts[x.role]=(counts[x.role]??0)+1;
const missingRoles=roles.filter(role=>counts[role]!==1);
const same=a.length===3&&a.every(x=>x.task_id===a[0].task_id&&x.project_id===a[0].project_id&&x.artifact_id===a[0].artifact_id&&x.artifact_revision===a[0].artifact_revision&&x.review_round===a[0].review_round&&JSON.stringify(x.requested_scopes)===JSON.stringify(a[0].requested_scopes));
const requested=a[0]?.requested_scopes??[];
const validScopes=['TEXT','IMAGE','VIDEO','AUDIO'];
const phase=(a[0]?.review_phase==='TEXT_PRECHECK')?'TEXT_PRECHECK':'FINAL_MEDIA';
const phaseScopes=phase==='TEXT_PRECHECK'?['TEXT']:validScopes;
const validScopeList=Array.isArray(requested)&&requested.length>0&&new Set(requested).size===requested.length&&requested.every(s=>validScopes.includes(s)&&phaseScopes.includes(s));
const requiredRoles=phase==='TEXT_PRECHECK'?['REVIEW-REQ','REVIEW-SYSTEM']:roles;
const hasInputErrors=a.some(x=>Array.isArray(x.input_errors)&&x.input_errors.length>0);
const validRoles=a.length===3&&!missingRoles.length&&same&&validScopeList&&a.every(x=>x.review_phase===phase);
const evidenceTypes={TEXT:['text_quote','transcript_quote'],IMAGE:['image_observation'],VIDEO:['video_frame','video_segment'],AUDIO:['audio_observation']};
function serverReceipt(x){const r=x.server_receipt;return !!r&&typeof r==='object'&&r.verified===true&&typeof r.review_id==='string'&&r.review_id.length>0&&r.artifact_revision===x.artifact_revision;}
function receiptsBacked(x){if(!serverReceipt(x)||!Array.isArray(x.evidence)||!x.evidence.length)return false;
return x.evidence.some(e=>e&&validScopes.includes(e.scope)&&evidenceTypes[e.scope].includes(e.evidence_type)&&((typeof e.source_asset_id==='string'&&e.source_asset_id)||(typeof e.source_text_revision==='string'&&e.source_text_revision)));}
function crediblePass(x){if(x.verdict!=='PASS'||!receiptsBacked(x)||!Array.isArray(x.checked_scopes))return false;
return requested.every(s=>x.checked_scopes.includes(s)&&x.scope_results?.[s]==='PASS'&&x.evidence.some(e=>e?.scope===s&&evidenceTypes[s].includes(e.evidence_type)&&((typeof e.source_asset_id==='string'&&e.source_asset_id)||(typeof e.source_text_revision==='string'&&e.source_text_revision))));}
const relevant=a.filter(x=>requiredRoles.includes(x.role));
const validResults=relevant.every(x=>['PASS','FAIL','BLOCKED'].includes(x.verdict));
const failed=relevant.some(x=>x.verdict==='FAIL'&&receiptsBacked(x));
const blocked=relevant.some(x=>x.verdict==='BLOCKED');
const allRequiredPass=!hasInputErrors&&validRoles&&validResults&&relevant.length===requiredRoles.length&&relevant.every(crediblePass);
const status=hasInputErrors?'BLOCKED_INVALID_INPUT':!validRoles||!validResults?'BLOCKED_INVALID_REVIEW_SET':failed?'CHANGES_REQUESTED':blocked?(phase==='TEXT_PRECHECK'?'BLOCKED_TEXT_REVIEW_NOT_CONNECTED':'BLOCKED_AWAITING_INTEGRATION'):allRequiredPass?(phase==='TEXT_PRECHECK'?'TEXT_PRECHECK_PASSED_AWAITING_OWNER':'AWAITING_OWNER_APPROVAL'):'BLOCKED_UNVERIFIED_EVIDENCE';
const verdicts=a.map(x=>({role:x.role,model:x.model,verdict:x.verdict,not_applicable_to_this_phase:x.not_applicable_to_this_phase??false,artifact_scope:x.artifact_scope,requested_scopes:x.requested_scopes,checked_scopes:x.checked_scopes??[],scope_results:x.scope_results??{},missing_inputs:x.missing_inputs,evidence:x.evidence,biggest_gap:x.biggest_gap}));
return[{json:{task_id:a[0]?.task_id??null,project_id:a[0]?.project_id??null,artifact_id:a[0]?.artifact_id??null,artifact_revision:a[0]?.artifact_revision??null,review_round:a[0]?.review_round??1,review_phase:phase,artifact_scope:a[0]?.artifact_scope??null,requested_scopes:requested,required_reviewers:requiredRoles,status,text_precheck_passed:phase==='TEXT_PRECHECK'&&allRequiredPass,all_passed:phase==='FINAL_MEDIA'&&allRequiredPass,final_release_approved:false,owner_approval_required:true,paid_calls_executed:false,quality_claim:false,server_verified:relevant.every(serverReceipt),phase_scopes:phaseScopes,reviewer_count:a.length,missing_or_duplicate_roles:missingRoles,input_errors:[...new Set(a.flatMap(x=>Array.isArray(x.input_errors)?x.input_errors:[]))],verdicts,next_action:status==='CHANGES_REQUESTED'?'return_evidenced_gap_to_original_builder':allRequiredPass?'wait_for_owner_approval':'do_not_dispatch_paid_models; connect trusted FastAPI QA API with receipt verification'}}];
